  var EMBEDDED_MISC_ASSETS = Object.freeze({"assets/misc_mo_xum_xue_sa_luoi.jpg":"data:image/jpeg;base64,","assets/misc_sinh_vien_bach_khoa_2h_sang.jpg":"data:image/jpeg;base64,","assets/misc_qua_bo_linh_vat_2.png":"data:image/png;base64,","assets/misc_dang_vien_tranh_cu_quoc_hoi.jpg":"data:image/jpeg;base64,","assets/misc_fan_ham_mo_1.jpg":"data:image/jpeg;base64,","assets/misc_fan_ham_mo_2.jpg":"data:image/jpeg;base64,","assets/misc_fan_ham_mo_3.jpg":"data:image/jpeg;base64,","assets/misc_fan_ham_mo_4.jpg":"data:image/jpeg;base64,","assets/misc_fan_ham_mo_5.jpg":"data:image/jpeg;base64,","assets/misc_fan_ham_mo_6.jpg":"data:image/jpeg;base64,","assets/misc_da_kiem_duyet_jumpscare.jpg":"data:image/jpeg;base64,"});
